        "d2bd7b4ec54c4bd5b9e0bab4a38b04ea": {
          "id": "d2bd7b4ec54c4bd5b9e0bab4a38b04ea",
          "name": "Get Or Create Asset By Serial Number",
          "script": "(function execute() {\nvaVars.asset_sys_id_selected = \"\";\nvar metadataGlideRecordHelper = new x_aleen_snguardian.MetadataGlideRecordHelper();\nvar user_entered_serial_number =  vaInputs.enter_badge_serial_number.toString();\nif(user_entered_serial_number!=\"\"){\n    var assetGr = new GlideRecordSecure('x_aleen_snguardian_asset');\n    assetGr.addQuery('serial',vaInputs.enter_badge_serial_number);\n    assetGr.addQuery('system',vaVars.badge_system);\n    assetGr.addQuery('type.code',vaVars.badge_type);\n    assetGr.setValue('status',metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_status_code',\"UNASSIGNED\"));\n    assetGr.query();\n    if(assetGr.next()){\n       vaVars.asset_sys_id_selected = assetGr.getUniqueValue()\n    }else{\n    //Creating new asset\n        \n        var badgeTypeSysId = metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_asset_type',vaVars.badge_type);\n        var assetGr = new GlideRecordSecure('x_aleen_snguardian_asset');\n        assetGr.initialize();\n        assetGr.setValue('serial', vaInputs.enter_badge_serial_number);\n        assetGr.setValue('system', vaVars.badge_system);\n        assetGr.setValue('type', badgeTypeSysId);\n        assetGr.setValue('status',metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_status_code',\"UNASSIGNED\"));\n        vaVars.asset_sys_id_selected = assetGr.insert();\n    }\n}\n\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n    if(vaVars.new_asset_id == \"\"){\n      return true;\n    }\n})()\n"
          }
        }
      },
